const slug=name=>name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
const narrative=(id,label,placeholder)=>({id,label,type:'textarea',placeholder,span:2});
const table=(id,label,columns,help,summaries)=>({id,label,type:'table',columns,help,span:2,...(summaries?{summaries}:{})});
const choice=(key,label,options)=>({key,label,type:'select',options});
// select()/text()/date() are the standalone-field counterparts to choice() — choice() is
// deliberately key-based (not id-based) because it's only ever used inside a table's columns
// array, where StructuredTable/ReportTable index a row by column.key. A top-level document field
// (rendered directly on a section, not inside a table) is looked up by field.id
// (DocumentWorkspace's Field component calls updateValue(field.id, value)), so it needs its own
// helper rather than reusing choice() with the wrong key. Mirrors the same select()/text()
// convention config/measureTemplates.js already established for its own standalone fields.
const select=(id,label,options)=>({id,label,type:'select',options});
const text=(id,label,placeholder='')=>({id,label,type:'text',placeholder});
const date=(id,label)=>({id,label,type:'date'});
// Phase 3 — calculated-field helpers. A calculate(values) function on a template is applied by
// DocumentWorkspace on every updateValue call and merged over the raw values ({...values,
// ...calculated}), the same pattern EVM Dashboard already established. These helpers extend that
// pattern to per-row table calculations: a row-level calc function returns only the derived
// column(s) for one row, and calcRows maps it across the whole table array, leaving every other
// column on the row untouched. Any field or column these calculations populate must also be
// marked calculated:true in its own definition — that flag is what tells DocumentWorkspace's
// Field/TableCell to render it as a read-only display instead of an editable input.
const toNumber=v=>{if(v===undefined||v===null||v==='')return null;const n=Number(String(v).replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null;};
const toDate=v=>{if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d;};
const round=(n,decimals=0)=>{const f=10**decimals;return Math.round(n*f)/f;};
// Whole calendar days between two date-like values. Positive means `end` is later than `start`
// (e.g. baselineDate -> actualForecastDate: positive = finished after baseline = behind schedule).
const daysBetween=(start,end)=>{const s=toDate(start),e=toDate(end);if(!s||!e)return '';return Math.round((e-s)/86400000);};
const calcRows=(rows,fn)=>(rows||[]).map(row=>({...row,...fn(row)}));
// Additive rollups (a total made of parts) treat a missing operand as 0, so a total is still
// meaningful with only one side entered. Difference/ratio calculations (variance, weighted score,
// exposure) instead require every operand present, returning '' when the inputs are incomplete —
// a variance or a probability x impact score computed against a missing value would be misleading,
// not just imprecise.
const sumOrBlank=(...values)=>{const parsed=values.map(toNumber);if(parsed.every(n=>n===null))return '';return round(parsed.reduce((total,n)=>total+(n||0),0),2);};
const diffOrBlank=(a,b,decimals=2)=>{const na=toNumber(a),nb=toNumber(b);return(na===null||nb===null)?'':round(nb-na,decimals);};
const productOrBlank=(a,b,decimals=2)=>{const na=toNumber(a),nb=toNumber(b);return(na===null||nb===null)?'':round(na*nb,decimals);};
const percentOrBlank=(amount,base,decimals=1)=>{const n=toNumber(amount),b=toNumber(base);return(n===null||b===null||b===0)?'':round((n/b)*100,decimals);};
