  'EVM Dashboard':{calculate:values=>{const pv=Number(values.pv)||0,ev=Number(values.ev)||0,ac=Number(values.ac)||0,bac=Number(values.bac)||0,cpi=ac?ev/ac:0,spi=pv?ev/pv:0,eac=cpi?bac/cpi:0;return{CPI:cpi.toFixed(2),SPI:spi.toFixed(2),CV:(ev-ac).toFixed(2),SV:(ev-pv).toFixed(2),EAC:eac.toFixed(2),ETC:(eac-ac).toFixed(2),VAC:(bac-eac).toFixed(2)};},sections:[{id:'evm-inputs',title:'EVM Inputs',guidance:'Use values from the approved cost and schedule baselines.',cols:2,fields:[{id:'pv',label:'Planned Value (PV)',type:'text'},{id:'ev',label:'Earned Value (EV)',type:'text'},{id:'ac',label:'Actual Cost (AC)',type:'text'},{id:'bac',label:'Budget at Completion (BAC)',type:'text'}]},{id:'forecast',title:'Calculated Performance and Interpretation',guidance:'Review calculated indicators, then explain drivers, forecast confidence, and corrective action.',cols:2,fields:[{id:'CPI',label:'Cost Performance Index (CPI)',type:'text',calculated:true},{id:'SPI',label:'Schedule Performance Index (SPI)',type:'text',calculated:true},{id:'CV',label:'Cost Variance (CV)',type:'text',calculated:true},{id:'SV',label:'Schedule Variance (SV)',type:'text',calculated:true},{id:'EAC',label:'Estimate at Completion (EAC)',type:'text',calculated:true},{id:'ETC',label:'Estimate to Complete (ETC)',type:'text',calculated:true},{id:'VAC',label:'Variance at Completion (VAC)',type:'text',calculated:true},narrative('interpretation','Interpretation','Explain CPI, SPI, variances, forecast, and management action.')]}]},
